import { isoOrNull, stableId } from '../core/contracts.js';
const STATUS=new Set(['SCHEDULED','ACTIVE','ONGOING_CAMPAIGN','COMPLETED','CANCELLED','UNKNOWN']);const PREC=new Set(['EXACT_PUBLIC','CITY','REGION','COUNTRY','NONE']);
export function normalizePublicAction(input={},now=Date.now()){
 if(!input.organization||!input.title||!input.officialSourceUrl)return null;const precision=PREC.has(input.locationPrecision)?input.locationPrecision:'NONE';let status=STATUS.has(input.status)?input.status:'UNKNOWN';const s=Date.parse(input.startsAt||''),e=Date.parse(input.endsAt||'');if(status==='UNKNOWN'){if(Number.isFinite(s)&&now<s)status='SCHEDULED';else if(Number.isFinite(s)&&Number.isFinite(e)&&now>=s&&now<=e)status='ACTIVE';else if(Number.isFinite(e)&&now>e)status='COMPLETED';else if(input.ongoing===true)status='ONGOING_CAMPAIGN';}
 const exact=precision==='EXACT_PUBLIC'&&Number.isFinite(input.lat)&&Number.isFinite(input.lon);return Object.freeze({actionId:input.actionId||stableId([input.organization,input.title,input.startsAt,input.officialSourceUrl]),organization:String(input.organization),title:String(input.title),activityType:input.activityType||'CAMPAIGN',topics:[...(input.topics||[])],status,startsAt:isoOrNull(input.startsAt),endsAt:isoOrNull(input.endsAt),country:input.country||null,region:input.region||null,city:input.city||null,locationPrecision:precision,lat:exact?input.lat:null,lon:exact?input.lon:null,mappable:exact||precision==='CITY'||precision==='REGION'||precision==='COUNTRY',officialSourceUrl:String(input.officialSourceUrl),participationUrl:input.participationUrl||null,truthClass:'OFFICIAL_NGO_SOURCE'});}
